mapper.select:
SELECT id
FROM course
WHERE id = #{id}
  AND school_id = #{schoolId}
FOR UPDATE

SELECT id
FROM course
WHERE id = #{id}
  AND school_id = #{schoolId}
  AND status = 'ACTIVE'
FOR UPDATE

SELECT COUNT(*)
FROM course_offering
WHERE course_id = #{id}

SELECT COUNT(*)
FROM course
WHERE id = #{id}
  AND school_id = #{schoolId}
  AND NOT (
      course_code = #{courseCode}
      AND target_grade_min = #{targetGradeMin}
      AND target_grade_max = #{targetGradeMax}
  )

SELECT COUNT(*)
FROM teacher
WHERE id = #{id}
  AND school_id = #{schoolId}
  AND status = 'ACTIVE'

SELECT id
FROM teacher
WHERE id = #{id}
  AND school_id = #{schoolId}
  AND status = 'ACTIVE'
FOR UPDATE

SELECT status
FROM course_offering
WHERE id = #{id}
  AND school_id = #{schoolId}
FOR UPDATE

SELECT COUNT(*)
FROM lesson_session
WHERE offering_id = #{id}
  AND status = 'SCHEDULED'
  AND TIMESTAMP(session_date, start_time) <= #{now}

SELECT COUNT(*)
FROM course_offering
WHERE id = #{id}
  AND school_id = #{schoolId}
  AND NOT (
      course_id = #{courseId}
      AND teacher_id = #{teacherId}
      AND offering_code = #{offeringCode}
      AND term = #{term}
      AND week_day = #{weekDay}
      AND start_time = #{startTime}
      AND end_time = #{endTime}
      AND start_date = #{startDate}
      AND end_date = #{endDate}
      AND enrollment_start = #{enrollmentStart}
      AND enrollment_end = #{enrollmentEnd}
      AND classroom = #{classroom}
      AND term_id <=> #{termId}
      AND plan_id <=> #{planId}
      AND room_id <=> #{roomId}
  )

SELECT id
FROM course_offering
WHERE teacher_id = #{teacherId}
  AND id != #{excludeOfferingId}
  AND week_day = #{weekDay}
  AND start_date <= #{endDate}
  AND end_date >= #{startDate}
  AND start_time < #{endTime}
  AND end_time > #{startTime}
  AND status NOT IN ('CANCELED', 'FINISHED')
ORDER BY id
LIMIT 1
FOR UPDATE

SELECT FROM course_offering o JOIN school s ON s.id = o.school_id JOIN course c ON c.id = o.course_id JOIN teacher t ON t.id = o.teacher_id LEFT JOIN academic_term trm ON trm.id = o.term_id LEFT JOIN school_service_plan plan ON plan.id = o.plan_id LEFT JOIN school_room room ON room.id = o.room_id
o.school_id = #{schoolId} AND o.teacher_id = #{teacherId}
ORDER BY o.start_date DESC, o.week_day, o.start_time, o.id

mapper.update:
UPDATE enrollment
SET status = 'CANCELED',
    canceled_at = CURRENT_TIMESTAMP(3),
    canceled_by = #{canceledBy}
WHERE offering_id = #{id}
  AND status = 'ENROLLED'

UPDATE lesson_session
SET status = 'CANCELED'
WHERE offering_id = #{id}
  AND status = 'SCHEDULED'
  AND TIMESTAMP(session_date, start_time) > #{now}
